 if(page==='cleanup')return v('Aquatic cleanup','PIP can remove simulated litter while leaving living things in place. Less litter helps protect habitats.','cleanup',[act('♻️ Collect model litter','sample','cleanup'),back]);
 if(page==='pressure'){const depths=[0,10,100,1000,4000,6000],d=depths[s.pressure];return v('Pressure model','Ocean model depth: '+d+' m. Approximate total pressure: '+Math.round(1+d/10)+' atmospheres. Pressure acts in all directions and increases with depth. These are teaching approximations, not dive limits.','pressure-'+s.pressure,[step('⬇️ Change model depth','pressure'),back]);}
 if(page==='depth'){const bands=[['Sunlit','roughly 0–200 m. Enough light may support photosynthesis; actual light penetration varies.'],['Twilight','roughly 200–1,000 m. Light fades and is generally insufficient for photosynthesis.'],['Midnight','roughly 1,000–4,000 m. Sunlight does not reach here.'],['Abyssal','roughly 4,000–6,000 m. Dark, cold and under high pressure.'],['Hadal','deeper than roughly 6,000 m, often in trenches. Not the depth of our home lake.']];return v('Depth zone: '+bands[s.depth][0],bands[s.depth][1]+' This is an ocean zonation model.','depth-'+s.depth,[step('⬇️ Next depth zone','depth'),back]);}
 if(page==='buoyancy'){const facts=['The sub is floating. An upward buoyant force comes from displaced water.','The model has balanced weight and buoyant force: neutral buoyancy.','Adding ballast increases mass in our fixed-volume model, so it tends to sink. Real submersibles have engineered controls.'];return v('Buoyancy and ballast',facts[s.ballast],'buoyancy-'+s.ballast,[step('⚖️ Change ballast','ballast'),go('🚤 Sub dock','dock'),back]);}
 if(page==='salinity')return v('Fresh and salty water',(s.salinity?'Salt-water model: at similar temperature, saltier water is denser.':'Freshwater model: our home lake is freshwater.')+' Density affects buoyancy. Real water density also depends on temperature and pressure.','salinity',[act('🧂 Compare fresh / salty','salinity'),back]);
 if(page==='volcano'){const facts=['Magma rises through Earth’s crust. This is a protected seafloor model.','At the seafloor, erupted molten rock is lava. Water can cool it into rock such as basalt.','Hydrothermal vents circulate seawater heated by rock. Not every vent lies on an erupting volcano.','Some microbes use chemical energy in chemosynthesis. They can support vent food webs without local sunlight. Deep ecosystems differ.'];return v('Underwater volcano model',facts[s.volcano],'volcano-'+s.volcano,[step('▶ Next model step','volcano'),act('🌋 Save basalt model sample','sample','basalt'),back]);}
