 travel:{hover:'<ellipse cx="100" cy="155" rx="38" ry="9" fill="#8adce8"/><path d="M82 171h36"/>',wheels:'<path d="M45 142h110"/><rect x="36" y="131" width="30" height="35" rx="8" fill="#29495d"/><rect x="134" y="131" width="30" height="35" rx="8" fill="#29495d"/><path stroke="#d0e4e6" d="M45 138v20m11-20v20m87-20v20m11-20v20"/>',climber:'<path fill="none" stroke-width="9" d="M64 72L35 45 18 73M136 72l29-27 17 28M62 126l-30 16-12 30M138 126l30 16 12 30"/>',swim:'<path fill="#65cbdc" d="M68 136l-32 30 40-8M132 136l32 30-40-8"/><ellipse cx="100" cy="154" rx="14" ry="17" fill="#9be8eb"/>'}[c.travel],
 trim:{none:'',wings:'<path fill="#c8edf2" d="M62 80L15 61l9 35 38 15M138 80l47-19-9 35-38 15"/>',fins:'<path fill="#65cbdc" d="M65 70L38 44l8 70M135 70l27-26-8 70"/>'}[c.trim],
