function crewMenu(){open('Choose your J.A.C.C. crew');panel.classList.add('crew-panel');paragraph('One tap selects your astronaut. Everyone can explore every activity.');const grid=document.createElement('div');grid.className='crew-grid';content.append(grid);for(const r of roster){const selected=characters.active[0]===r[0];const b=button('',()=>{characters.select(r[0]);persist();updateCrew();close();announce(r[0]+' selected. '+r[2]);speak(r[0]+'. '+r[2])},grid);b.className='crew-card';b.dataset.badge=String(roster.indexOf(r)+1);b.setAttribute('aria-label',r[0]+', '+crewDescription(r[0])+', '+r[1]+' suit. '+r[2]);b.setAttribute('aria-pressed',String(selected));const icon=document.createElement('span');icon.className='crew-portrait';icon.style.setProperty('--suit',suitColors[r[1]]);icon.setAttribute('aria-hidden','true');const name=document.createElement('strong');name.textContent=r[0];const detail=document.createElement('small');detail.textContent=crewDescription(r[0])+' • '+r[1]+' • '+r[2];const badge=document.createElement('span');badge.textContent=selected?'✓ Selected':'Select';b.append(icon,name,detail,badge);}paragraph('Temporary suit-color placeholders. Approved character artwork will replace these.');}
