function showSuitPower(id,step=0,target=state.last){const v=suitPowerView(characters.active[0],id,step,{zone:state.zone,target,farm:state.farm,position:[state.x,state.y]});if(!v)return;open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=suitArt(v.art);const p=document.createElement('p');p.textContent=v.heading+'. '+v.text;info.append(art,p);content.append(info);button('✨ Reveal in world',()=>{state.suit=activateSuit(state.suit,characters.active[0],id);persist();close();announce(v.title+' active. Tap a highlighted place to investigate.');});button('▶ Next / repeat',()=>showSuitPower(id,v.step+1,v.target));if(v.travel)button('🏗️ Try this plan',()=>{state.suit.overlay=null;persist();close();select(objects.find(o=>o.id===v.travel));});if(v.target)button('👆 Explore this place',()=>{state.suit.overlay=null;persist();close();select(objects.find(o=>o.id===v.target));});button('🔊 Listen',()=>readJournal(v.heading+'. '+v.text));button('← Suit powers',suitMenu);}
const suitButton=document.createElement('button');suitButton.id='suit';suitButton.setAttribute('aria-label','Astronaut suit powers');suitButton.innerHTML='✨<span>Suit</span>';suitButton.onclick=suitMenu;document.querySelector('nav').append(suitButton);
const suitOverlayImages=new Map();function drawSuitOverlay(){const power=suitPowerFor(characters.active[0],state.suit.overlay);if(!power)return;const key=power.id+'-'+state.zone+'-'+state.aquatic.habitat+'-'+state.excavation.level;if(!suitOverlayImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(suitOverlay(power,state.zone,state.aquatic.habitat,state.excavation.level));suitOverlayImages.set(key,img);if(suitOverlayImages.size>3)suitOverlayImages.delete(suitOverlayImages.keys().next().value)}const img=suitOverlayImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,0,0,1000,600);}
